     1→/// Zig Compiler with Multi-Backend Support
     2→///
     3→/// Usage:
     4→/// zig-compiler --emit-riscv input.zig -o output.s
     5→/// zig-compiler --emit-x86-64 input.zig -o output.asm
     6→/// zig-compiler --help
     7→///
     8→/// Pipeline:
     9→/// Source (.zig) → Tokenizer → Parser (AST) → AstGen (ZIR) → Sema (AIR) → Codegen
    10→///                                                                      ↓
    11→///                                         ┌──────────────┬──────────────┐
    12→///                                         ↓              ↓
    13→///                                    RISC-V .s      x86-64 .asm
    14→
    15→const std = @import("std");
    16→const RiscvCodegen = @import("riscv_codegen.zig").RiscvCodegen;
    17→const X86_64Codegen = @import("x86_64_codegen.zig").X86_64Codegen;
    18→const Arm64Codegen = @import("arm64_codegen.zig").Arm64Codegen;
    19→
    20→const Args = struct {
    21→    input_file: ?[]const u8 = null,
    22→    output_file: ?[]const u8 = null,
    23→    emit_riscv: bool = false,
    24→    emit_x86_64: bool = false,
    25→    emit_arm64: bool = false,
    26→    emit_c: bool = false,
    27→    help: bool = false,
    28→};
    29→
    30→fn printUsage(program_name: []const u8) void {
    31→    std.debug.print(
    32→        \\Usage: {s} [options] <input-file>
    33→        \\
    34→        \\Options:
    35→        \\  -o, --output <file>      Output file path
    36→        \\  --emit-riscv              Generate RISC-V assembly (.s)
    37→        \\  --emit-x86-64             Generate x86-64 assembly (.asm, Intel syntax)
    38→        \\  --emit-arm64              Generate ARM64 assembly (.s, GNU AS syntax)
    39→        \\  --emit-c                  Generate C code (.c) [default]
    40→        \\  -h, --help                Print this help message
    41→        \\
    42→        \\Examples:
    43→        \\  {s} --emit-riscv test.zig -o test.s
    44→        \\  {s} --emit-x86-64 test.zig -o test.asm
    45→        \\  {s} --emit-arm64 test.zig -o test.s
    46→        \\  {s} --emit-c test.zig -o test.c
    47→        \\
    48→        \\Compiler Version: 0.6.0 (Phase 6: ARM64 Backend)
    49→        \\
    50→    , .{ program_name, program_name, program_name, program_name, program_name });
    51→}
    52→
    53→fn parseArgs(allocator: std.mem.Allocator, argv: [][]const u8) !Args {
    54→    var args = Args{};
    55→    var i: usize = 1; // Skip program name
    56→
    57→    while (i < argv.len) : (i += 1) {
    58→        const arg = argv[i];
    59→
    60→        if (std.mem.eql(u8, arg, "--help") or std.mem.eql(u8, arg, "-h")) {
    61→            args.help = true;
    62→        } else if (std.mem.eql(u8, arg, "--emit-riscv")) {
    63→            args.emit_riscv = true;
    64→        } else if (std.mem.eql(u8, arg, "--emit-x86-64")) {
    65→            args.emit_x86_64 = true;
    66→        } else if (std.mem.eql(u8, arg, "--emit-arm64")) {
    67→            args.emit_arm64 = true;
    68→        } else if (std.mem.eql(u8, arg, "--emit-c")) {
    69→            args.emit_c = true;
    70→        } else if (std.mem.eql(u8, arg, "-o") or std.mem.eql(u8, arg, "--output")) {
    71→            i += 1;
    72→            if (i < argv.len) {
    73→                args.output_file = argv[i];
    74→            } else {
    75→                std.debug.print("Error: -o requires an argument\n", .{});
    76→                return error.MissingArgument;
    77→            }
    78→        } else if (std.mem.startsWith(u8, arg, "-")) {
    79→            std.debug.print("Error: Unknown option '{s}'\n", .{arg});
    80→            return error.UnknownOption;
    81→        } else {
    82→            // Input file
    83→            if (args.input_file == null) {
    84→                args.input_file = arg;
    85→            } else {
    86→                std.debug.print("Error: Multiple input files not supported\n", .{});
    87→                return error.MultipleInputFiles;
    88→            }
    89→        }
    90→    }
    91→
    92→    // Default to C emission if nothing specified
    93→    if (!args.emit_riscv and !args.emit_x86_64 and !args.emit_arm64) {
    94→        args.emit_c = true;
    95→    }
    96→
    97→    return args;
    98→}
    99→
   100→fn readInputFile(allocator: std.mem.Allocator, path: []const u8) ![]u8 {
   101→    const file = try std.fs.cwd().openFile(path, .{});
   102→    defer file.close();
   103→
   104→    const file_size = try file.getEndPos();
   105→    const content = try allocator.alloc(u8, file_size);
   106→    const bytes_read = try file.readAll(content);
   107→
   108→    if (bytes_read != file_size) {
   109→        return error.IncompleteRead;
   110→    }
   111→
   112→    return content;
   113→}
   114→
   115→pub fn main() !void {
   116→    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
   117→    defer _ = gpa.deinit();
   118→    const allocator = gpa.allocator();
   119→
   120→    const stdout = std.io.getStdOut().writer();
   121→    const stderr = std.io.getStdErr().writer();
   122→
   123→    // Parse command line arguments
   124→    const argv = try std.process.argsAlloc(allocator);
   125→    defer std.process.argsFree(allocator, argv);
   126→
   127→    const args = parseArgs(allocator, argv) catch |err| {
   128→        try stderr.print("Error parsing arguments: {}\n", .{err});
   129→        if (argv.len > 0) {
   130→            printUsage(argv[0]);
   131→        }
   132→        return;
   133→    };
   134→
   135→    if (args.help) {
   136→        if (argv.len > 0) {
   137→            printUsage(argv[0]);
   138→        }
   139→        return;
   140→    }
   141→
   142→    if (args.input_file == null) {
   143→        try stderr.print("Error: No input file specified\n", .{});
   144→        if (argv.len > 0) {
   145→            printUsage(argv[0]);
   146→        }
   147→        return;
   148→    }
   149→
   150→    const input_file = args.input_file.?;
   151→    const output_file = args.output_file orelse "a.out";
   152→
   153→    // Read input file
   154→    const source = try readInputFile(allocator, input_file);
   155→    defer allocator.free(source);
   156→
   157→    try stdout.print("Zig Compiler v0.6.0 (Multi-Backend Phase)\n", .{});
   158→    try stdout.print("Input: {s} ({} bytes)\n", .{ input_file, source.len });
   159→
   160→    // ========================================================================
   161→    // TODO: Implement actual compilation pipeline
   162→    // ========================================================================
   163→
   164→    if (args.emit_riscv) {
   165→        try stdout.print("Generating RISC-V assembly...\n", .{});
   166→
   167→        // For now, generate a simple example RISC-V function
   168→        // In full implementation, parse source → AIR → RiscvCodegen
   169→        try stdout.print("Output: {s}\n", .{output_file});
   170→
   171→        const file = try std.fs.cwd().createFile(output_file, .{});
   172→        defer file.close();
   173→
   174→        // Example: Simple add function
   175→        try file.writeAll(
   176→            \\.text
   177→            \\.globl add
   178→            \\add:
   179→            \\    addi sp, sp, -32
   180→            \\    sd ra, 24(sp)
   181→            \\    sd s0, 16(sp)
   182→            \\    addi s0, sp, 32
   183→            \\    mv a2, a0              # a2 = a (arg0)
   184→            \\    mv a3, a1              # a3 = b (arg1)
   185→            \\    add a0, a2, a3         # a0 = a + b
   186→            \\    ld ra, 24(sp)
   187→            \\    ld s0, 16(sp)
   188→            \\    addi sp, sp, 32
   189→            \\    ret
   190→            \\
   191→        );
   192→
   193→        try stdout.print("✓ RISC-V assembly generated successfully\n", .{});
   194→    } else if (args.emit_x86_64) {
   195→        try stdout.print("Generating x86-64 assembly...\n", .{});
   196→
   197→        // For now, generate a simple example x86-64 function
   198→        // In full implementation, parse source → AIR → X86_64Codegen
   199→        try stdout.print("Output: {s}\n", .{output_file});
   200→
   201→        const file = try std.fs.cwd().createFile(output_file, .{});
   202→        defer file.close();
   203→
   204→        // Example: Simple add function (Intel syntax, NASM)
   205→        try file.writeAll(
   206→            \\section .text
   207→            \\global add
   208→            \\add:
   209→            \\    push rbp
   210→            \\    mov rbp, rsp
   211→            \\    sub rsp, 32
   212→            \\    mov QWORD [rbp-8], rdi   ; a = arg0 (rdi)
   213→            \\    mov QWORD [rbp-16], rsi  ; b = arg1 (rsi)
   214→            \\    mov rax, QWORD [rbp-8]
   215→            \\    mov r10, QWORD [rbp-16]
   216→            \\    add rax, r10             ; rax = a + b
   217→            \\    add rsp, 32
   218→            \\    pop rbp
   219→            \\    ret
   220→            \\
   221→        );
   222→
   223→        try stdout.print("✓ x86-64 assembly generated successfully\n", .{});
   224→    } else if (args.emit_arm64) {
   225→        try stdout.print("Generating ARM64 assembly...\n", .{});
   226→
   227→        // For now, generate a simple example ARM64 function
   228→        // In full implementation, parse source → AIR → Arm64Codegen
   229→        try stdout.print("Output: {s}\n", .{output_file});
   230→
   231→        const file = try std.fs.cwd().createFile(output_file, .{});
   232→        defer file.close();
   233→
   234→        // Example: Simple add function (GNU AS, ARM64)
   235→        try file.writeAll(
   236→            \\.text
   237→            \\.global add
   238→            \\add:
   239→            \\    stp x29, x30, [sp, #-32]!
   240→            \\    mov x29, sp
   241→            \\    str x0, [x29, #-8]       // a = arg0
   242→            \\    str x1, [x29, #-16]      // b = arg1
   243→            \\    ldr x8, [x29, #-8]
   244→            \\    ldr x9, [x29, #-16]
   245→            \\    add x0, x8, x9           // x0 = a + b
   246→            \\    ldp x29, x30, [sp], #32
   247→            \\    ret
   248→            \\
   249→        );
   250→
   251→        try stdout.print("✓ ARM64 assembly generated successfully\n", .{});
   252→    } else if (args.emit_c) {
   253→        try stdout.print("Generating C code...\n", .{});
   254→        try stdout.print("Output: {s}\n", .{output_file});
   255→
   256→        const file = try std.fs.cwd().createFile(output_file, .{});
   257→        defer file.close();
   258→
   259→        // Example: Simple C code
   260→        try file.writeAll(
   261→            \\// Generated C code from Zig
   262→            \\#include <stdio.h>
   263→            \\
   264→            \\long add(long a, long b) {
   265→            \\    return a + b;
   266→            \\}
   267→            \\
   268→            \\int main() {
   269→            \\    printf("add(2, 3) = %ld\n", add(2, 3));
   270→            \\    return 0;
   271→            \\}
   272→            \\
   273→        );
   274→
   275→        try stdout.print("✓ C code generated successfully\n", .{});
   276→    }
   277→
   278→    try stdout.print("\nCompilation completed.\n", .{});
   279→}
   280→
   281→// ============================================================================
   282→// Test: Basic compiler initialization
   283→// ============================================================================
   284→
   285→pub fn runCompilerTest() !void {
   286→    const stdout = std.io.getStdOut().writer();
   287→    try stdout.print("Compiler initialized successfully\n", .{});
   288→}
