     1→/// ARM64 (AArch64) Code Generator
     2→///
     3→/// Targets: Apple Silicon (arm64), Linux AArch64, other ARM64 systems
     4→/// Syntax: GNU AS / LLVM AS
     5→/// ABI: AAPCS64 (ARM 64-bit Calling Convention)
     6→///
     7→/// Register Layout:
     8→/// - x0-x7:    Argument/return registers (caller-saved)
     9→/// - x8-x15:   Temporary registers (caller-saved)
    10→/// - x16-x17:  Intra-procedure-call temporary (caller-saved)
    11→/// - x18:      Platform register (reserved)
    12→/// - x19-x28:  Callee-saved
    13→/// - x29:      Frame pointer (fp) - reserved, not allocated
    14→/// - x30:      Link register (lr) - reserved, not allocated
    15→/// - sp:       Stack pointer - reserved
    16→/// - xzr:      Zero register (read-only)
    17→
    18→const std = @import("std");
    19→const Allocator = std.mem.Allocator;
    20→
    21→pub const Register = enum(u5) {
    22→    x0 = 0, x1 = 1, x2 = 2, x3 = 3, x4 = 4, x5 = 5, x6 = 6, x7 = 7,
    23→    x8 = 8, x9 = 9, x10 = 10, x11 = 11, x12 = 12, x13 = 13, x14 = 14, x15 = 15,
    24→    x16 = 16, x17 = 17, x18 = 18, x19 = 19, x20 = 20, x21 = 21, x22 = 22, x23 = 23,
    25→    x24 = 24, x25 = 25, x26 = 26, x27 = 27, x28 = 28, x29 = 29, x30 = 30,
    26→};
    27→
    28→pub const Arm64Codegen = struct {
    29→    allocator: Allocator,
    30→    output: std.ArrayList(u8),
    31→    used_regs: [31]bool,      // x0-x30 (x29, x30 reserved but tracked)
    32→    label_counter: u32,
    33→    current_frame_size: i64,
    34→
    35→    pub fn init(allocator: Allocator) Arm64Codegen {
    36→        return Arm64Codegen{
    37→            .allocator = allocator,
    38→            .output = std.ArrayList(u8).init(allocator),
    39→            .used_regs = [_]bool{false} ** 31,
    40→            .label_counter = 0,
    41→            .current_frame_size = 0,
    42→        };
    43→    }
    44→
    45→    pub fn deinit(self: *Arm64Codegen) void {
    46→        self.output.deinit();
    47→    }
    48→
    49→    /// Get register name (x0, x1, ..., x30)
    50→    fn getRegisterName(reg: Register) []const u8 {
    51→        return switch (reg) {
    52→            .x0 => "x0", .x1 => "x1", .x2 => "x2", .x3 => "x3", .x4 => "x4", .x5 => "x5", .x6 => "x6", .x7 => "x7",
    53→            .x8 => "x8", .x9 => "x9", .x10 => "x10", .x11 => "x11", .x12 => "x12", .x13 => "x13", .x14 => "x14", .x15 => "x15",
    54→            .x16 => "x16", .x17 => "x17", .x18 => "x18", .x19 => "x19", .x20 => "x20", .x21 => "x21", .x22 => "x22", .x23 => "x23",
    55→            .x24 => "x24", .x25 => "x25", .x26 => "x26", .x27 => "x27", .x28 => "x28", .x29 => "x29", .x30 => "x30",
    56→        };
    57→    }
    58→
    59→    /// Allocate a register for temporary use
    60→    /// Priority: x8-x15 (caller-saved temps) → x0-x7 (args) → x19-x28 (callee-saved)
    61→    pub fn allocReg(self: *Arm64Codegen) ?Register {
    62→        // Temps first: x8-x15
    63→        for (8..16) |i| {
    64→            if (!self.used_regs[i]) {
    65→                self.used_regs[i] = true;
    66→                return @enumFromInt(@as(u5, @intCast(i)));
    67→            }
    68→        }
    69→        // Args: x0-x7
    70→        for (0..8) |i| {
    71→            if (!self.used_regs[i]) {
    72→                self.used_regs[i] = true;
    73→                return @enumFromInt(@as(u5, @intCast(i)));
    74→            }
    75→        }
    76→        // Callee-saved: x19-x28
    77→        for (19..29) |i| {
    78→            if (!self.used_regs[i]) {
    79→                self.used_regs[i] = true;
    80→                return @enumFromInt(@as(u5, @intCast(i)));
    81→            }
    82→        }
    83→        return null; // All registers used
    84→    }
    85→
    86→    /// Free a register
    87→    pub fn freeReg(self: *Arm64Codegen, reg: Register) void {
    88→        const idx = @intFromEnum(reg);
    89→        if (idx < 31) {
    90→            self.used_regs[idx] = false;
    91→        }
    92→    }
    93→
    94→    /// Emit raw instruction line
    95→    fn emit(self: *Arm64Codegen, comptime fmt: []const u8, args: anytype) !void {
    96→        try self.output.writer().print(fmt ++ "\n", args);
    97→    }
    98→
    99→    // ========================================================================
   100→    // Step 1: Basic Arithmetic Operations
   101→    // ========================================================================
   102→
   103→    /// movz x0, #42 (or movz + movk for 64-bit immediates)
   104→    pub fn emitMovImm(self: *Arm64Codegen, dst: Register, value: i64) !void {
   105→        const uval = @as(u64, @bitCast(value));
   106→
   107→        // For small values, just movz
   108→        if (uval <= 0xFFFF) {
   109→            try self.emit("    movz {s}, #{x}", .{ getRegisterName(dst), uval });
   110→        } else if (uval <= 0xFFFFFFFF) {
   111→            // Two 16-bit chunks
   112→            const lo = uval & 0xFFFF;
   113→            const hi = (uval >> 16) & 0xFFFF;
   114→            try self.emit("    movz {s}, #{x}", .{ getRegisterName(dst), hi });
   115→            try self.emit("    movk {s}, #{x}, lsl #16", .{ getRegisterName(dst), lo });
   116→        } else {
   117→            // Full 64-bit: 4 chunks
   118→            try self.emit("    movz {s}, #{x}", .{ getRegisterName(dst), (uval >> 48) & 0xFFFF });
   119→            try self.emit("    movk {s}, #{x}, lsl #32", .{ getRegisterName(dst), (uval >> 32) & 0xFFFF });
   120→            try self.emit("    movk {s}, #{x}, lsl #16", .{ getRegisterName(dst), (uval >> 16) & 0xFFFF });
   121→            try self.emit("    movk {s}, #{x}", .{ getRegisterName(dst), uval & 0xFFFF });
   122→        }
   123→    }
   124→
   125→    /// mov x0, x1 (register move)
   126→    pub fn emitMov(self: *Arm64Codegen, dst: Register, src: Register) !void {
   127→        try self.emit("    mov {s}, {s}", .{ getRegisterName(dst), getRegisterName(src) });
   128→    }
   129→
   130→    /// add x0, x1, x2 (3-operand add)
   131→    pub fn emitAdd(self: *Arm64Codegen, dst: Register, lhs: Register, rhs: Register) !void {
   132→        try self.emit("    add {s}, {s}, {s}", .{ getRegisterName(dst), getRegisterName(lhs), getRegisterName(rhs) });
   133→    }
   134→
   135→    /// sub x0, x1, x2 (3-operand sub)
   136→    pub fn emitSub(self: *Arm64Codegen, dst: Register, lhs: Register, rhs: Register) !void {
   137→        try self.emit("    sub {s}, {s}, {s}", .{ getRegisterName(dst), getRegisterName(lhs), getRegisterName(rhs) });
   138→    }
   139→
   140→    /// mul x0, x1, x2 (3-operand multiply)
   141→    pub fn emitMul(self: *Arm64Codegen, dst: Register, lhs: Register, rhs: Register) !void {
   142→        try self.emit("    mul {s}, {s}, {s}", .{ getRegisterName(dst), getRegisterName(lhs), getRegisterName(rhs) });
   143→    }
   144→
   145→    /// sdiv x0, x1, x2 (signed divide)
   146→    pub fn emitSdiv(self: *Arm64Codegen, dst: Register, lhs: Register, rhs: Register) !void {
   147→        try self.emit("    sdiv {s}, {s}, {s}", .{ getRegisterName(dst), getRegisterName(lhs), getRegisterName(rhs) });
   148→    }
   149→
   150→    /// msub x0, x1, x2, x3 (dst = x3 - x1*x2, used for modulo: msub result, quot, divisor, dividend)
   151→    pub fn emitMsub(self: *Arm64Codegen, dst: Register, a: Register, b: Register, c: Register) !void {
   152→        try self.emit("    msub {s}, {s}, {s}, {s}", .{ getRegisterName(dst), getRegisterName(a), getRegisterName(b), getRegisterName(c) });
   153→    }
   154→
   155→    /// neg x0, x1 (negate: x0 = 0 - x1)
   156→    pub fn emitNeg(self: *Arm64Codegen, dst: Register, src: Register) !void {
   157→        try self.emit("    neg {s}, {s}", .{ getRegisterName(dst), getRegisterName(src) });
   158→    }
   159→
   160→    /// cmp x0, x1 (compare)
   161→    pub fn emitCmp(self: *Arm64Codegen, lhs: Register, rhs: Register) !void {
   162→        try self.emit("    cmp {s}, {s}", .{ getRegisterName(lhs), getRegisterName(rhs) });
   163→    }
   164→
   165→    /// cset x0, eq/ne/lt/le/gt/ge (conditional set: 1 if true, 0 if false)
   166→    pub fn emitCset(self: *Arm64Codegen, dst: Register, cond: []const u8) !void {
   167→        try self.emit("    cset {s}, {s}", .{ getRegisterName(dst), cond });
   168→    }
   169→
   170→    /// ret (return)
   171→    pub fn emitRet(self: *Arm64Codegen) !void {
   172→        try self.emit("    ret", .{});
   173→    }
   174→
   175→    // ========================================================================
   176→    // Step 2: Function Prologue/Epilogue and Stack Access
   177→    // ========================================================================
   178→
   179→    /// stp x29, x30, [sp, #-N]! (save frame pointer and link register, pre-decrement stack)
   180→    /// mov x29, sp (set frame pointer)
   181→    pub fn emitFunctionPrologue(self: *Arm64Codegen, frame_size: i64) !void {
   182→        // Align to 16 bytes (AAPCS64 requirement)
   183→        const aligned_frame_size = ((frame_size + 15) / 16) * 16;
   184→        self.current_frame_size = aligned_frame_size;
   185→
   186→        try self.emit("    stp x29, x30, [sp, #-{}]!", .{aligned_frame_size});
   187→        try self.emit("    mov x29, sp", .{});
   188→    }
   189→
   190→    /// ldp x29, x30, [sp], #N (restore frame pointer and link register, post-increment)
   191→    /// ret (return)
   192→    pub fn emitFunctionEpilogue(self: *Arm64Codegen) !void {
   193→        try self.emit("    ldp x29, x30, [sp], #{}", .{self.current_frame_size});
   194→        try self.emit("    ret", .{});
   195→    }
   196→
   197→    /// str x0, [x29, #-8] (store register to stack)
   198→    pub fn emitStr(self: *Arm64Codegen, src: Register, offset: i64) !void {
   199→        try self.emit("    str {s}, [x29, #{}]", .{ getRegisterName(src), offset });
   200→    }
   201→
   202→    /// ldr x0, [x29, #-8] (load register from stack)
   203→    pub fn emitLdr(self: *Arm64Codegen, dst: Register, offset: i64) !void {
   204→        try self.emit("    ldr {s}, [x29, #{}]", .{ getRegisterName(dst), offset });
   205→    }
   206→
   207→    /// bl function_name (branch with link - function call)
   208→    pub fn emitBl(self: *Arm64Codegen, target: []const u8) !void {
   209→        try self.emit("    bl {s}", .{target});
   210→    }
   211→
   212→    /// .global symbol_name (declare global function)
   213→    pub fn emitGlobal(self: *Arm64Codegen, name: []const u8) !void {
   214→        try self.emit(".global {s}", .{name});
   215→    }
   216→
   217→    /// symbol_name: (function label)
   218→    pub fn emitFunctionLabel(self: *Arm64Codegen, name: []const u8) !void {
   219→        try self.emit("{s}:", .{name});
   220→    }
   221→
   222→    // ========================================================================
   223→    // Step 3: Control Flow
   224→    // ========================================================================
   225→
   226→    /// Generate unique label (.L0, .L1, etc.)
   227→    pub fn newLabel(self: *Arm64Codegen, allocator: Allocator) ![]u8 {
   228→        const label = try std.fmt.allocPrint(allocator, ".L{}", .{self.label_counter});
   229→        self.label_counter += 1;
   230→        return label;
   231→    }
   232→
   233→    /// .L0: (emit label)
   234→    pub fn emitLabel(self: *Arm64Codegen, label: []const u8) !void {
   235→        try self.emit("{s}:", .{label});
   236→    }
   237→
   238→    /// b .L0 (unconditional branch)
   239→    pub fn emitB(self: *Arm64Codegen, label: []const u8) !void {
   240→        try self.emit("    b {s}", .{label});
   241→    }
   242→
   243→    /// b.eq .L0 (branch if equal)
   244→    pub fn emitBEq(self: *Arm64Codegen, label: []const u8) !void {
   245→        try self.emit("    b.eq {s}", .{label});
   246→    }
   247→
   248→    /// b.ne .L0 (branch if not equal)
   249→    pub fn emitBNe(self: *Arm64Codegen, label: []const u8) !void {
   250→        try self.emit("    b.ne {s}", .{label});
   251→    }
   252→
   253→    /// b.lt .L0 (branch if signed less than)
   254→    pub fn emitBLt(self: *Arm64Codegen, label: []const u8) !void {
   255→        try self.emit("    b.lt {s}", .{label});
   256→    }
   257→
   258→    /// b.le .L0 (branch if signed less than or equal)
   259→    pub fn emitBLe(self: *Arm64Codegen, label: []const u8) !void {
   260→        try self.emit("    b.le {s}", .{label});
   261→    }
   262→
   263→    /// b.gt .L0 (branch if signed greater than)
   264→    pub fn emitBGt(self: *Arm64Codegen, label: []const u8) !void {
   265→        try self.emit("    b.gt {s}", .{label});
   266→    }
   267→
   268→    /// b.ge .L0 (branch if signed greater than or equal)
   269→    pub fn emitBGe(self: *Arm64Codegen, label: []const u8) !void {
   270→        try self.emit("    b.ge {s}", .{label});
   271→    }
   272→
   273→    /// cbz x0, .L0 (compare with zero and branch if zero)
   274→    pub fn emitCbz(self: *Arm64Codegen, reg: Register, label: []const u8) !void {
   275→        try self.emit("    cbz {s}, {s}", .{ getRegisterName(reg), label });
   276→    }
   277→
   278→    /// cbnz x0, .L0 (compare with zero and branch if not zero)
   279→    pub fn emitCbnz(self: *Arm64Codegen, reg: Register, label: []const u8) !void {
   280→        try self.emit("    cbnz {s}, {s}", .{ getRegisterName(reg), label });
   281→    }
   282→
   283→    /// test x0 (cmp x0, #0 - for condition checking)
   284→    pub fn emitTest(self: *Arm64Codegen, reg: Register) !void {
   285→        try self.emit("    cmp {s}, #0", .{getRegisterName(reg)});
   286→    }
   287→};
